CREATE TABLE fee_structures (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, class_id text NOT NULL, name text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), currency text NOT NULL DEFAULT 'INR' CHECK(currency='INR'), active boolean NOT NULL DEFAULT true, UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,class_id) REFERENCES classes(org_id,id));
CREATE TABLE invoices (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, student_id text NOT NULL, title text NOT NULL, due_date date NOT NULL, total_minor integer NOT NULL CHECK(total_minor>0), paid_minor integer NOT NULL DEFAULT 0 CHECK(paid_minor>=0 AND paid_minor<=total_minor), currency text NOT NULL DEFAULT 'INR' CHECK(currency='INR'), event_key text NOT NULL, pending_order_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), UNIQUE(org_id,event_key), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id));
CREATE TABLE invoice_items (id text PRIMARY KEY, org_id text NOT NULL, invoice_id text NOT NULL, structure_id text NOT NULL, description text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), FOREIGN KEY(org_id,invoice_id) REFERENCES invoices(org_id,id), FOREIGN KEY(org_id,structure_id) REFERENCES fee_structures(org_id,id));
CREATE TABLE payment_orders (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, student_id text NOT NULL, account_id text NOT NULL, actor_id text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), currency text NOT NULL DEFAULT 'INR' CHECK(currency='INR'), event_key text NOT NULL, provider_order_id text UNIQUE, status text NOT NULL DEFAULT 'creating' CHECK(status IN ('creating','created','pending_verification','uncertain','captured','failed','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), UNIQUE(org_id,event_key), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES users(org_id,id), FOREIGN KEY(org_id,account_id) REFERENCES integration_accounts(org_id,id));
ALTER TABLE invoices ADD FOREIGN KEY(org_id,pending_order_id) REFERENCES payment_orders(org_id,id);
CREATE TABLE payment_order_items (org_id text NOT NULL, order_id text NOT NULL, invoice_id text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), PRIMARY KEY(org_id,order_id,invoice_id), FOREIGN KEY(org_id,order_id) REFERENCES payment_orders(org_id,id), FOREIGN KEY(org_id,invoice_id) REFERENCES invoices(org_id,id));
CREATE TABLE payments (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, student_id text NOT NULL, order_id text, provider_payment_id text UNIQUE, method text NOT NULL, reference text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), currency text NOT NULL CHECK(currency='INR'), confirmed_at timestamptz NOT NULL DEFAULT now(), verified_by text, UNIQUE(org_id,id), UNIQUE(org_id,reference), FOREIGN KEY(org_id,order_id) REFERENCES payment_orders(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,verified_by) REFERENCES users(org_id,id));
CREATE UNIQUE INDEX payment_order_once ON payments(org_id,order_id) WHERE order_id IS NOT NULL;
CREATE TABLE payment_allocations (org_id text NOT NULL, payment_id text NOT NULL, invoice_id text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), PRIMARY KEY(org_id,payment_id,invoice_id), FOREIGN KEY(org_id,payment_id) REFERENCES payments(org_id,id), FOREIGN KEY(org_id,invoice_id) REFERENCES invoices(org_id,id));
CREATE TABLE receipts (id text PRIMARY KEY, org_id text NOT NULL, payment_id text NOT NULL, number text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), UNIQUE(org_id,payment_id), UNIQUE(org_id,number), FOREIGN KEY(org_id,payment_id) REFERENCES payments(org_id,id));
CREATE TABLE ledger_entries (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, invoice_id text NOT NULL, payment_id text, event_key text NOT NULL, kind text NOT NULL CHECK(kind IN ('charge','payment','adjustment','refund')), amount_minor integer NOT NULL CHECK(amount_minor<>0), reason text NOT NULL, actor_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,event_key), FOREIGN KEY(org_id,invoice_id) REFERENCES invoices(org_id,id), FOREIGN KEY(org_id,payment_id) REFERENCES payments(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES users(org_id,id));
ALTER TABLE message_recipients ADD FOREIGN KEY(org_id,invoice_id) REFERENCES invoices(org_id,id);
